  `appointment_date` DATE NOT NULL,
  `status` ENUM('pending', 'completed', 'cancelled') NOT NULL,
  `description` TEXT NOT NULL,
  `image_url` VARCHAR(255) NULL,
  `repaired_date` DATE NOT NULL,
  `repair_cost_cents` INTEGER NOT NULL,
  `repair_details` TEXT NOT NULL,
  `created_at` TIMESTAMP NOT NULL,
  `updated_at` TIMESTAMP NULL,
  PRIMARY KEY (`maintenance_id`),
  INDEX `fk_maintenance_requests_rooms1_idx` (`room_id` ASC) VISIBLE,
  CONSTRAINT `fk_maintenance_requests_rooms1`
    FOREIGN KEY (`room_id`)
    REFERENCES `mydb`.`rooms` (`room_id`)
    ON DELETE NO ACTION
    ON UPDATE NO ACTION)
ENGINE = InnoDB;


