-- -----------------------------------------------------
-- Table `mydb`.`meter_readings`
-- -----------------------------------------------------
CREATE TABLE IF NOT EXISTS `mydb`.`meter_readings` (
  `meter_reading_id` INT NOT NULL AUTO_INCREMENT,
  `meter_batch_id` INT NOT NULL,
  `room_id` INT NOT NULL,
  -- 014: ยอมให้เป็น NULL ได้ — NULL = ฝั่งนี้ยังไม่ได้จดในรอบนี้ · 0 = จดแล้วอ่านได้ 0
  -- หน้าจอกรอกทีละฝั่ง ถ้าเขียนอีกฝั่งเป็น 0 ไว้ก่อน ฝั่งนั้นจะหยุดไล่หาเลขครั้งก่อน
  `water_previous_reading` DECIMAL(10,2) NULL,
  `water_current_reading` DECIMAL(10,2) NULL,
  `water_units_used` DECIMAL(10,2) NULL,
  `is_water_over_cycle` TINYINT(1) NULL,
  `electric_previous_reading` DECIMAL(10,2) NULL,
  `electric_current_reading` DECIMAL(10,2) NULL,
  `electric_units_used` DECIMAL(10,2) NULL,
  `is_electric_over_cycle` TINYINT(1) NULL,
  `created_at` TIMESTAMP NOT NULL,
  `updated_at` TIMESTAMP NULL,
  PRIMARY KEY (`meter_reading_id`),
  INDEX `fk_meter_readings_meter_batches1_idx` (`meter_batch_id` ASC) VISIBLE,
  INDEX `fk_meter_readings_rooms1_idx` (`room_id` ASC) VISIBLE,
  CONSTRAINT `fk_meter_readings_meter_batches1`
    FOREIGN KEY (`meter_batch_id`)
    REFERENCES `mydb`.`meter_batches` (`batch_id`)
    ON DELETE NO ACTION
    ON UPDATE NO ACTION,
  CONSTRAINT `fk_meter_readings_rooms1`
    FOREIGN KEY (`room_id`)
    REFERENCES `mydb`.`rooms` (`room_id`)
    ON DELETE NO ACTION
    ON UPDATE NO ACTION)
ENGINE = InnoDB;


-- -----------------------------------------------------
-- Table `mydb`.`invoices`
-- -----------------------------------------------------
CREATE TABLE IF NOT EXISTS `mydb`.`invoices` (
  `invoice_id` INT NOT NULL AUTO_INCREMENT,
  `contract_id` INT NOT NULL,
  `invoice_number` VARCHAR(50) NOT NULL,
  `billing_month` VARCHAR(7) NOT NULL,
  `issue_date` DATE NOT NULL,
  `due_date` DATE NOT NULL,
  `status` ENUM('unpaid', 'partial_paid', 'paid', 'cancelled') NOT NULL,
  -- เพิ่มใน 012: บิลรายเดือน (ออกยกล็อตจากใบจดมิเตอร์) vs ใบแจ้งหนี้ทั่วไป (ออกใบเดี่ยว)
  `invoice_type` ENUM('monthly', 'general') NOT NULL DEFAULT 'monthly',
  -- เพิ่มใน 012: บิลรายเดือนมาจากการจดมิเตอร์รอบไหน (ใบแจ้งหนี้ทั่วไปเป็น NULL)
  `meter_batch_id` INT NULL,
  `exempt_amount_cents` INTEGER NOT NULL,
  `taxable_amount_cents` INTEGER NOT NULL,
  `vat_amount_cents` INTEGER NOT NULL,
  `total_amount_cents` INTEGER NOT NULL,
  `note` TEXT NULL,
  `created_at` TIMESTAMP NOT NULL,
  `updated_at` TIMESTAMP NULL,
  -- เพิ่มใน 012: บิลที่ถูกยกเลิกต้องรู้ว่ายกเลิกเมื่อไหร่
  `cancelled_at` TIMESTAMP NULL,
  PRIMARY KEY (`invoice_id`),
  -- 012: เลขที่ใบแจ้งหนี้ห้ามซ้ำ และหนึ่งสัญญาออกบิลรายเดือนได้เดือนละใบ (ที่ยังไม่ยกเลิก)
  UNIQUE INDEX `idx_invoices_number` (`invoice_number` ASC) VISIBLE,
  INDEX `fk_invoices_contracts1_idx` (`contract_id` ASC) VISIBLE,
  CONSTRAINT `fk_invoices_contracts1`
    FOREIGN KEY (`contract_id`)
    REFERENCES `mydb`.`contracts` (`contract_id`)
    ON DELETE NO ACTION
    ON UPDATE NO ACTION)
ENGINE = InnoDB;


-- -----------------------------------------------------
-- Table `mydb`.`invoice_items`
